{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--ink:#102028;--muted:#667780;--accent:#6aa6a1;--card:#ffffff}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(0deg,rgba(255,255,255,0.6),rgba(255,255,255,0.6));border-bottom:1px solid #e8efef}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#9ad0cc);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-size:15px}
    .cta{background:var(--accent);color:white;padding:8px 14px;border-radius:8px;text-decoration:none;font-weight:600}

    main{max-width:900px;margin:28px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center}
    .hero .eyebrow{color:var(--muted);font-weight:600}
    h1{margin:6px 0 0;font-size:28px}
    p.lead{color:var(--muted);line-height:1.5}

    .stack{display:grid;gap:18px;margin-top:22px}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(16,32,40,0.04);opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
    .card.revealed{opacity:1;transform:none}
    .pillars{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
    .pill{background:#f6fcfb;border-radius:10px;padding:12px}

    .myth-list{display:grid;gap:10px}
    .myth{display:flex;gap:12px;align-items:flex-start}
    .myth strong{color:var(--accent)}

    footer{max-width:900px;margin:30px auto;padding:22px;color:var(--muted);font-size:13px}

    /* pattern behind footer area */
    .back-plate{background-image:url('/assets/img/pattern.svg');background-size:260px;background-position:top right;background-repeat:no-repeat;padding:36px;border-radius:14px}

    /* Modal / Try it */
    .overlay{position:fixed;inset:0;background:rgba(6,12,12,0.45);display:none;align-items:center;justify-content:center;padding:20px;z-index:60}
    .overlay.active{display:flex}
    .modal{background:var(--card);padding:20px;border-radius:12px;width:100%;max-width:540px;box-shadow:0 18px 40px rgba(2,8,8,0.28)}
    .modal h3{margin:0 0 8px}
    .modal .controls{display:flex;gap:8px;margin-bottom:12px}
    .btn{padding:8px 12px;border-radius:8px;background:#eef6f5;border:0;font-weight:600;cursor:pointer}
    .btn.primary{background:var(--accent);color:white}
    .circle{width:120px;height:120px;border-radius:50%;margin:14px auto;background:linear-gradient(135deg,#e6fbfa,#d9f3f1);display:flex;align-items:center;justify-content:center;font-weight:700}

    /* reduced motion */
    @media (prefers-reduced-motion:reduce){.card{transition:none}}

  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">{{BUSINESS_NAME?:B}}</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Welcome</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Fees</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <div class="eyebrow">About the practice</div>
        <h1>Psychotherapy shaped around how you actually live</h1>
        <p class="lead">I offer ongoing clinical support through a membership model — a steady place for reflection, planning, and small adjustments that build over time. Sessions blend evidence-informed approaches with realistic, daily practices we can adapt to your life.</p>
      </div>
      <div style="display:flex;gap:12px;align-items:center">
        <button class="btn primary" id="open-exercise">Try a short exercise</button>
        <a href="book.html" class="btn">Schedule an intake</a>
      </div>
    </section>

    <div class="stack">
      <article class="card" data-reveal>
        <h3>How I work</h3>
        <p style="color:var(--muted)">My work is collaborative and pragmatic. We clarify goals, map small habits that support those aims, and test what actually fits your week. I bring clinical training and an emphasis on safety, confidentiality, and practical steps you can try between sessions.</p>
      </article>

      <article class="card" data-reveal>
        <h3>Common misconceptions</h3>
        <div class="myth-list">
          <div class="myth"><div style="width:6px;height:6px;background:var(--accent);border-radius:50%;margin-top:6px"></div><div><strong>Myth:</strong> Therapy must always be intensive to matter.<br><strong>Truth:</strong> Consistent, steady attention often makes change more manageable; the pace is matched to you.</div></div>
          <div class="myth"><div style="width:6px;height:6px;background:var(--accent);border-radius:50%;margin-top:6px"></div><div><strong>Myth:</strong> There's one right method for everyone.<br><strong>Truth:</strong> We tailor methods to your needs — what feels coherent and doable for you.</div></div>
        </div>
      </article>

      <div class="card back-plate" data-reveal>
        <h3>Core commitments</h3>
        <div class="pillars">
          <div class="pill"><strong>Confidential, values-based care</strong><div style="color:var(--muted)">Conversations remain private within clinical limits; I will explain any exceptions in our first meeting.</div></div>
          <div class="pill"><strong>Membership rhythm</strong><div style="color:var(--muted)">Monthly access with predictable scheduling and a focus on steady practice rather than one-off fixes.</div></div>
          <div class="pill"><strong>Clear boundaries</strong><div style="color:var(--muted)">I am not available for crises outside sessions. If you are in crisis, contact local emergency services or a crisis line immediately.</div></div>
        </div>
      </div>
    </div>

    <div style="margin-top:20px;display:flex;gap:12px">
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <a class="btn" href="contact.html">Connect via email</a>
    </div>
  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto">
      <div style="margin-bottom:8px">Clinical note: Services are provided by a licensed clinician. They are not a substitute for emergency services. If you are at immediate risk, call emergency services or a crisis line in your area.</div>
      <div style="color:var(--muted)">Confidentiality: Your records are kept secure; limits to confidentiality (e.g., safety concerns, legal requirements) will be discussed before treatment begins.</div>
      <div style="margin-top:10px;color:var(--muted)">Scope: I generally work with adults on mood, anxiety, relationship concerns, and life transitions. Specifics will be clarified in initial conversations.</div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="overlay" class="overlay" role="dialog" aria-modal="true" aria-labelledby="exercise-title">
    <div class="modal" id="modal" tabindex="-1">
      <h3 id="exercise-title">Try a brief practice</h3>
      <div style="color:var(--muted);margin-bottom:8px">Choose a short guided option to ground attention. These are standalone exercises and do not replace therapy.</div>
      <div class="controls">
        <button class="btn" data-mode="breath">Breathing</button>
        <button class="btn" data-mode="journal">Journaling</button>
        <button class="btn" data-mode="intention">Set an intention</button>
        <button class="btn" id="close-exercise">Close</button>
      </div>
      <div id="exercise-area">
        <!-- populated by JS -->
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ els.forEach(e=>e.classList.add('revealed')); return }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting){ entry.target.classList.add('revealed'); io.unobserve(entry.target) }
        })
      },{threshold:0.12});
      els.forEach(el=>io.observe(el));
    })();

    // Guided exercise modal
    (function(){
      const overlay = document.getElementById('overlay');
      const open = document.getElementById('open-exercise');
      const close = document.getElementById('close-exercise');
      const area = document.getElementById('exercise-area');
      let focusedBefore = null;

      function openModal(){ focusedBefore = document.activeElement; overlay.classList.add('active'); document.getElementById('modal').focus(); }
      function closeModal(){ overlay.classList.remove('active'); area.innerHTML=''; if(focusedBefore) focusedBefore.focus(); }

      open.addEventListener('click', openModal);
      close.addEventListener('click', closeModal);
      overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeModal() });
      document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeModal() });

      document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click', ()=>{
        const mode = btn.getAttribute('data-mode');
        area.innerHTML='';
        if(mode==='breath') renderBreath(area);
        else if(mode==='journal') renderJournal(area);
        else if(mode==='intention') renderIntent(area);
      }));

      function renderBreath(root){
        root.innerHTML = '<div style="text-align:center"><div class="circle" id="breath-circle">Breathe</div><div style="color:var(--muted);margin-top:8px">Follow the prompts: inhale — hold — exhale. (3 cycles)</div><div style="margin-top:12px;text-align:center"><button class="btn primary" id="start-breath">Start</button></div></div>';
        const btn = document.getElementById('start-breath');
        const circle = document.getElementById('breath-circle');
        btn.addEventListener('click', ()=>{
          if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
            circle.textContent = 'Inhale... Hold... Exhale...';
            setTimeout(()=>circle.textContent='Done',2500);
            return;
          }
          let cycle = 0;
          function step(){
            if(cycle>=3){ circle.textContent='Done'; return }
            circle.textContent='Inhale'; circle.style.transform='scale(1.18)';
            setTimeout(()=>{ circle.textContent='Hold'; setTimeout(()=>{ circle.textContent='Exhale'; circle.style.transform='scale(1)'; setTimeout(()=>{ cycle++; step(); },1200); },800) },1200);
          }
          step();
        });
      }

      function renderJournal(root){
        root.innerHTML = '<div><label style="font-weight:700">Quick journaling: 5 minutes</label><div style="color:var(--muted);margin:8px 0">Write freely for a short timed session. Your words are stored locally on this device only.</div><textarea id="journal-text" rows="6" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6efee"></textarea><div style="display:flex;gap:8px;margin-top:8px"><button class="btn primary" id="start-journal">Start 5m timer</button><button class="btn" id="save-journal">Save</button></div><div id="journal-status" style="color:var(--muted);margin-top:6px"></div></div>';
        const textarea = document.getElementById('journal-text');
        const status = document.getElementById('journal-status');
        const start = document.getElementById('start-journal');
        const save = document.getElementById('save-journal');
        textarea.value = localStorage.getItem('quick-journal')||'';
        save.addEventListener('click', ()=>{ localStorage.setItem('quick-journal', textarea.value); status.textContent='Saved locally.' });
        start.addEventListener('click', ()=>{
          let time = 300; // seconds
          if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){ status.textContent = 'Timer started for 5 minutes.'; return }
          status.textContent = format(time);
          const iv = setInterval(()=>{
            time--; status.textContent = format(time);
            if(time<=0){ clearInterval(iv); status.textContent='Time complete.' }
          },1000);
        });
        function format(s){ const m = Math.floor(s/60); const sec = s%60; return m+':'+(sec<10?'0'+sec:sec) }
      }

      function renderIntent(root){
        root.innerHTML = '<div><label style="font-weight:700">Set a small intention</label><div style="color:var(--muted);margin:8px 0">Write one concrete thing you will try this week.</div><input id="intent-input" type="text" placeholder="I will..." style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6efee"><div style="display:flex;gap:8px;margin-top:8px"><button class="btn primary" id="save-intent">Save intention</button></div><div id="intent-status" style="color:var(--muted);margin-top:6px"></div></div>';
        const input = document.getElementById('intent-input');
        const save = document.getElementById('save-intent');
        const status = document.getElementById('intent-status');
        input.value = localStorage.getItem('weekly-intent')||'';
        save.addEventListener('click', ()=>{ localStorage.setItem('weekly-intent', input.value); status.textContent='Stored for this device.' });
      }

    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Areas of Focus — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--ink:#0d1b1b;--muted:#556b6b;--accent:#7bb1aa}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:var(--ink);background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 26px;border-bottom:1px solid #eef6f5}
    .logo{width:42px;height:42px;border-radius:9px;background:linear-gradient(135deg,var(--accent),#cfeee9);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    main{max-width:980px;margin:22px auto;padding:20px}
    .lead{color:var(--muted);margin-bottom:18px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .list{display:grid;gap:12px}
    .spec{background:#fbfffe;padding:14px;border-radius:10px;border:1px solid #eef7f6}
    .spec h4{margin:0 0 6px}
    .case{font-size:14px;color:var(--muted)}
    .aside{background:linear-gradient(180deg,#fbfffe,#f3fbfa);padding:14px;border-radius:10px}
    .try{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:14px}
    .btn{padding:8px 12px;border-radius:8px;background:#eef6f5;border:0;cursor:pointer}
    .btn.primary{background:var(--accent);color:white;font-weight:700}
    footer{max-width:980px;margin:28px auto;padding:18px;color:var(--muted);font-size:13px}

    /* reveal */
    .spec{opacity:0;transform:translateY(12px);transition:opacity .5s ease,transform .5s ease}
    .spec.revealed{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.spec{transition:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">{{BUSINESS_NAME?:B}}</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="about.html">Practitioner</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Approach</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <h1>Focus areas</h1>
    <p class="lead">I work with adults to make transportable changes that honor how you live and who you care for. Below are some common reasons people seek support here.</p>

    <div class="grid">
      <div class="list">
        <article class="spec" data-reveal>
          <h4>Anxiety and worry</h4>
          <div class="case">Short- and long-term support for patterns of persistent worry, panic symptoms, and avoidance. We use exposure planning, cognitive tools, and habit redesign to increase livability.</div>
        </article>

        <article class="spec" data-reveal>
          <h4>Mood regulation</h4>
          <div class="case">Work on consistent routines, activity planning, and mood-tracking to create steadier days. Interventions are matched to your schedule and resources.</div>
        </article>

        <article class="spec" data-reveal>
          <h4>Life transitions & relationship work</h4>
          <div class="case">Support through role changes, parenting shifts, separation, or relationship navigation. We aim for clarity in values and practical decisions aligned with them.</div>
        </article>

        <article class="spec" data-reveal>
          <h4>Attention & executive habit support</h4>
          <div class="case">If organizing tasks or keeping a routine feels difficult, we consider structure adjustments, environmental design, and brief behavioral experiments.</div>
        </article>
      </div>

      <aside class="aside">
        <div style="font-weight:700">How I present care</div>
        <div style="color:var(--muted);margin-top:8px">I generally offer ongoing care through a membership: regular check-ins, easy scheduling, and flexible session lengths for people balancing work and life demands. Pricing and specifics are shared during a consult.</div>

        <div class="try">
          <button class="btn primary" id="open-exercise-2">Try a short practice</button>
          <a class="btn" href="book.html">Request consult</a>
        </div>

        <div style="margin-top:12px;color:var(--muted);font-size:13px">Note: If you are in crisis, please call local emergency services or a crisis line. I do not provide emergency response through messaging.</div>
      </aside>
    </div>

    <div style="margin-top:18px;display:flex;gap:10px">
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <a class="btn" href="faq.html">Read our FAQ</a>
    </div>
  </main>

  <footer>
    <div style="max-width:980px;margin:0 auto">Confidentiality and scope: Conversations are private within clinical limits. If you have questions about fit or availability, contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}.</div>
  </footer>

  <!-- Modal reused locally -->
  <div id="overlay-2" class="overlay" style="position:fixed;inset:0;background:rgba(6,12,12,0.45);display:none;align-items:center;justify-content:center;padding:20px;z-index:60">
    <div class="modal" style="background:white;padding:20px;border-radius:12px;width:100%;max-width:520px" id="modal-2" tabindex="-1">
      <h3 id="exercise-title-2">Quick practice</h3>
      <div style="color:var(--muted);margin-bottom:8px">A brief guided breathing or journaling prompt. Not crisis support.</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn" data-mode="breath">Breathing</button>
        <button class="btn" data-mode="journal">Journaling</button>
        <button class="btn" id="close-2">Close</button>
      </div>
      <div id="exercise-area-2" style="margin-top:12px"></div>
    </div>
  </div>

  <script>
    // lightweight reveal
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const targets = document.querySelectorAll('[data-reveal]');
      if(reduced){ targets.forEach(t=>t.classList.add('revealed')); return }
      const obs = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('revealed'); obs.unobserve(e.target) } }) },{threshold:0.1});
      targets.forEach(t=>obs.observe(t));
    })();

    // modal logic similar to other pages
    (function(){
      const overlay = document.getElementById('overlay-2');
      const modal = document.getElementById('modal-2');
      document.getElementById('open-exercise-2').addEventListener('click', ()=>{ overlay.style.display='flex'; modal.focus(); });
      document.getElementById('close-2').addEventListener('click', ()=>{ overlay.style.display='none' });
      overlay.addEventListener('click',(e)=>{ if(e.target===overlay) overlay.style.display='none' });

      document.querySelectorAll('#overlay-2 [data-mode]').forEach(btn=>btn.addEventListener('click',()=>{
        const mode = btn.getAttribute('data-mode'); const area = document.getElementById('exercise-area-2'); area.innerHTML='';
        if(mode==='breath') area.innerHTML = '<div style="text-align:center"><div style="width:100px;height:100px;border-radius:50%;background:#eefcfb;display:inline-flex;align-items:center;justify-content:center;font-weight:700" id="c">Breathe</div><div style="margin-top:8px;color:var(--muted)">3 gentle cycles</div></div><div style="margin-top:10px;text-align:center"><button class="btn primary" id="bstart">Start</button></div>';
        if(mode==='journal') area.innerHTML = '<div><textarea id="j2" rows="5" style="width:100%;padding:10px;border-radius:8px"></textarea><div style="margin-top:8px;text-align:right"><button class="btn primary" id="jsave">Save</button></div></div>';
        setTimeout(()=>{
          if(mode==='breath'){
            const b = document.getElementById('bstart'); const c = document.getElementById('c'); b.addEventListener('click',()=>{ if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){ c.textContent='Inhale...Hold...Exhale'; setTimeout(()=>c.textContent='Done',2500); return } let i=0; function run(){ if(i>=3){ c.textContent='Done'; return } c.textContent='Inhale'; c.style.transform='scale(1.18)'; setTimeout(()=>{ c.textContent='Hold'; setTimeout(()=>{ c.textContent='Exhale'; c.style.transform='scale(1)'; i++; setTimeout(run,900); },700) },1200); } run(); });
          }
          if(mode==='journal'){ document.getElementById('jsave').addEventListener('click',()=>{ const t=document.getElementById('j2').value; localStorage.setItem('spec-journal',t); alert('Saved locally.'); }) }
        },60);
      }))
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Method & Process — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fdfc;--ink:#071818;--muted:#4f6a6a;--accent:#89bfb4}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;background:transparent}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#daefea);display:flex;align-items:center;justify-content:center;color:white}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    main{max-width:960px;margin:20px auto;padding:22px}
    h1{margin-top:0}
    .process{display:grid;gap:18px}
    .step{background:white;padding:16px;border-radius:12px;border-left:4px solid var(--accent);opacity:0;transform:translateY(14px);transition:opacity .6s ease,transform .6s ease}
    .step.revealed{opacity:1;transform:none}
    .step h4{margin:0 0 6px}
    .note{color:var(--muted);font-size:14px}
    .membership{background:linear-gradient(180deg,#ffffff,#f8fffd);padding:14px;border-radius:12px;margin-top:12px}
    .btn{padding:8px 12px;border-radius:8px;border:0;cursor:pointer}
    .btn.primary{background:var(--accent);color:white;font-weight:700}
    footer{max-width:960px;margin:28px auto;padding:18px;color:var(--muted);font-size:13px}
    @media (prefers-reduced-motion:reduce){.step{transition:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">{{BUSINESS_NAME?:B}}</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
